import { useForm } from '@tanstack/react-form'

type Person = { name: string; age: number }

export default function App() {
  const form = useForm({
    defaultValues: { people: [] as Person[] },
    onSubmit: ({ value }) => console.log(value),
  })

  return (
    <form.Field name="people" mode="array">
      {(field) => (
        <div>
          {field.state.value.map((person, i) => (
            <div key={i}>
              <input
                value={person.name}
                onChange={(e) => {
                  const people = [...field.state.value]
                  people[i] = { ...people[i], name: e.target.value }
                  field.handleChange(people)
                }}
              />
              <button type="button" onClick={() => field.removeValue(i)}>
                Remove
              </button>
            </div>
          ))}
          <button type="button" onClick={() => field.pushValue({ name: '', age: 0 })}>
            Add person
          </button>
        </div>
      )}
    </form.Field>
  )
}

