import { useForm } from '@tanstack/react-form'

const form = useForm({
  defaultValues: { username: '' },
  validators: {
    onDynamicAsyncDebounceMs: 500,
    onDynamicAsync: async ({ value }) => {
      if (!value.username) return { username: 'Username is required' }
      const response = await fetch(`/api/users/${value.username}`)
      return response.ok ? undefined : { username: 'Username is already taken' }
    },
  },
})

